def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        intervals = [i for i in intervals if i[0] < i[1]]
        if not intervals:
            return []

        intervals.sort()

        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            # Check if current overlaps or touches last
            if current[0] <= last[1]:
                # Merge by extending the end
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    result = []

    for a_interval in a_merged:
        a_start, a_end = a_interval
        current_ranges = [[a_start, a_end]]

        # Subtract each b interval from current ranges
        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap
                    # Keep the part before b_start
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    # Keep the part after b_end
                    if c_end > b_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    return merge_intervals(result)

